function reportToCommandWindow(surfaceModel, diffusion, photophysics, opts)
    import membrane_tracking.fluctuating_miet.*

    fprintf('[fluctuating MIET] method: %s\n', surfaceModel.method);
    fprintf(['  curvature   true %+.4g   naive %+.4g   moment %+.4g   ' ...
        'reported %+.4g +/- %.3g 1/um\n'], opts.curvaturePerUm, ...
        surfaceModel.naive.curvaturePerUm, ...
        surfaceModel.moment.curvaturePerUm, ...
        surfaceModel.curvaturePerUm, surfaceModel.curvatureSigmaPerUm);
    fprintf('  tip height  true %.4g   reported %.4g +/- %.3g um\n', ...
        opts.tipHeightUm, surfaceModel.tipHeightUm, ...
        surfaceModel.tipHeightSigmaUm);
    if isfield(surfaceModel,'topography') && surfaceModel.topography.isValid
        fprintf('  posterior topography RMSE %.3g um over %d snapshots\n', ...
            surfaceModel.topography.rmseUm, ...
            numel(surfaceModel.topography.snapshotFrame));
    end
    if isfield(surfaceModel.moment,'attenuationFactor')
        fprintf(['  regression-dilution attenuation %.3f (naive slope is ' ...
            'this fraction of the truth)\n'], ...
            surfaceModel.moment.attenuationFactor);
    end
    if isfield(surfaceModel,'identifiability') && ...
            isfield(surfaceModel.identifiability,'profileSigmaPerUm')
        id = surfaceModel.identifiability;
        fprintf(['  field rms %.4g um, correlation length %.4g um, ' ...
            'confounding ratio %.2f\n'], surfaceModel.fieldRmsUm, ...
            surfaceModel.fieldCorrelationLengthUm, id.confoundingRatio);
        fprintf(['  profile 95%% interval for kappa [%+.4g %+.4g]; ' ...
            'profile/Fisher sigma ratio %.2f\n'], ...
            id.profileInterval95PerUm(1), id.profileInterval95PerUm(2), ...
            id.profileOverFisherSigmaRatio);
        if id.confoundingRatio > 0.5 && id.confoundingRatio < 2
            fprintf(['  WARNING: the fitted field varies on the scale of ' ...
                'the observed patch. Curvature and fluctuation are not ' ...
                'separable in this regime; treat kappa as an upper bound ' ...
                'on what the data can support.\n']);
        end
    end
    fprintf(['[surface diffusion] true D %.4g, MSD %.4g, MLE %.4g +/- %.3g, ' ...
        'sampled truth %.4g um^2/s\n'], opts.diffusionUm2PerS, ...
        diffusion.DMsdCorrectedUm2PerS, diffusion.DFisherMLEUm2PerS, ...
        diffusion.diffusionFisherSigmaUm2PerS, ...
        diffusion.truthValidation.fullSurfaceLag1DiffusionUm2PerS);
    fprintf('  gate acceptance %.3f, censoring correction %d, %d steps\n', ...
        diffusion.meanGateAcceptanceProbability, ...
        diffusion.gateCensoringCorrectionApplied, ...
        diffusion.nIndependentStepsForFisher);
    if photophysics.fractionFramesWithMultipleBrightMolecules > 0
        fprintf(['  NOTE: %.2f%% of frames held more than one bright ' ...
            'molecule; the single-emitter model is violated there.\n'], ...
            100*photophysics.fractionFramesWithMultipleBrightMolecules);
    end
end
